<script setup>
import { computed, onMounted, reactive, ref, shallowRef } from 'vue'
import { api } from '../services/api.js'
import { logout, session } from '../session.js'
import { useRouter } from 'vue-router'

const router=useRouter()
const tab=ref('users')
const users=ref([])
const total=ref(0)
const totalPages=ref(0)
const page=ref(0)
const loading=ref(false)
const error=ref('')
const notice=ref('')
const filters=reactive({query:'',role:'',status:''})
const busy=reactive({})
const selected=ref(null)
const audits=ref([])
const confirmAction=shallowRef(null)
const temporary=ref(null)
const importJobs=ref([])
const searchIndex=ref(null)

const rangeLabel=computed(()=>total.value?`${page.value*20+1}–${Math.min((page.value+1)*20,total.value)} / ${total.value}`:'0 个账号')

function statusLabel(user){if(user.anonymizedAt)return '已匿名化';if(user.deletedAt)return '待匿名化';return user.status==='ACTIVE'?'使用中':'已停用'}
function statusTone(user){if(user.anonymizedAt)return 'anonymized';if(user.deletedAt)return 'deleted';return user.status==='ACTIVE'?'active':'disabled'}
function date(value){if(!value)return '—';return new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value))}
function maskedEmail(value){if(!value)return '—';const [name,domain]=value.split('@');return `${name?.slice(0,2)||''}***@${domain||'—'}`}
function canChange(user){return user.id!==session.user?.id&&!user.anonymizedAt}

async function loadUsers(nextPage=page.value){loading.value=true;error.value='';try{const result=await api.listAdminUsers({...filters,page:nextPage,size:20});users.value=result.items;total.value=result.total;totalPages.value=result.totalPages;page.value=result.page}catch(exception){error.value=exception.message||'账号列表加载失败'}finally{loading.value=false}}
async function loadOperations(){try{const [jobs,index]=await Promise.all([api.listRecipeImportJobs({page:0,size:20}),api.getSearchIndex()]);importJobs.value=jobs.items;searchIndex.value=index}catch(exception){error.value=exception.message||'运维状态加载失败'}}
async function chooseUser(user){selected.value=user;audits.value=[];try{const result=await api.getAdminUserAudit(user.id,{page:0,size:20});audits.value=result.items}catch(exception){error.value=exception.message||'审计记录加载失败'}}
function ask(title,body,label,run,danger=false){confirmAction.value={title,body,label,run,danger}}
async function confirm(){const action=confirmAction.value;if(!action)return;confirmAction.value=null;await action.run()}
async function act(user,key,operation,success){busy[user.id]=true;error.value='';try{await operation();notice.value=success;setTimeout(()=>{notice.value=''},2600);await loadUsers();if(selected.value?.id===user.id)await chooseUser(users.value.find(item=>item.id===user.id)||user)}catch(exception){error.value=conflictMessage(exception)}finally{busy[user.id]=false}}
function conflictMessage(exception){const messages={LAST_ADMIN_REQUIRED:'必须至少保留一个有效管理员',ADMIN_SELF_ACTION_FORBIDDEN:'不能对自己的管理员账号执行此操作',USER_ANONYMIZED:'账号已匿名化，无法恢复',USER_UNAVAILABLE:'账号当前不可用',INDEX_REBUILD_IN_PROGRESS:'已有索引重建任务在执行'};return messages[exception.code]||exception.message||'操作失败'}
function toggleStatus(user){const next=user.status==='ACTIVE'?'DISABLED':'ACTIVE';ask(next==='DISABLED'?'停用这个账号？':'重新启用账号？',next==='DISABLED'?'该账号的全部会话会立即失效，且无法继续登录。':'账号恢复登录权限，已有会话不会恢复。',next==='DISABLED'?'确认停用':'确认启用',()=>act(user,'status',()=>api.setAdminUserStatus(user.id,next),next==='DISABLED'?'账号已停用':'账号已启用'),next==='DISABLED')}
function toggleRole(user){const next=user.role==='ADMIN'?'USER':'ADMIN';ask(next==='ADMIN'?'授予管理员权限？':'移除管理员权限？',next==='ADMIN'?'该账号将可以管理全部用户账号。':'该账号的现有会话会立即失效。',next==='ADMIN'?'授予权限':'移除权限',()=>act(user,'role',()=>api.setAdminUserRole(user.id,next),'角色已更新'),next==='USER')}
function revoke(user){ask('强制退出全部设备？','所有刷新会话会立即撤销，用户需要重新登录。','确认强退',()=>act(user,'revoke',()=>api.revokeAdminUserSessions(user.id),'全部会话已撤销'),true)}
function remove(user){ask('删除这个账号？','账号将进入 90 天恢复期，之后自动匿名化。业务流水和审计记录会保留。','确认删除',()=>act(user,'delete',()=>api.deleteAdminUser(user.id),'账号已进入删除恢复期'),true)}
function restore(user){ask('恢复这个账号？','账号身份数据仍在保留期内，将恢复为使用中状态，但历史会话不会恢复。','确认恢复',()=>act(user,'restore',()=>api.restoreAdminUser(user.id),'账号已恢复'))}
function resetPassword(user){ask('生成一次性临时密码？','现有会话会立即撤销。临时密码仅展示一次，24 小时内必须修改。','生成密码',async()=>{busy[user.id]=true;try{temporary.value=await api.resetAdminUserPassword(user.id);await loadUsers()}catch(exception){error.value=conflictMessage(exception)}finally{busy[user.id]=false}},true)}
async function copyPassword(){if(temporary.value?.temporaryPassword){await navigator.clipboard.writeText(temporary.value.temporaryPassword);notice.value='临时密码已复制'}}
function closeTemporary(){temporary.value=null}
async function retryImport(job){busy[job.id]=true;try{await api.retryRecipeImportJob(job.id);await loadOperations();notice.value='导入任务已重新排队'}catch(exception){error.value=conflictMessage(exception)}finally{busy[job.id]=false}}
function rebuildIndex(){ask('重建搜索索引？','系统会创建新版本集合；全部数据写入成功后才切换线上索引。','开始重建',async()=>{try{await api.rebuildSearchIndex();await loadOperations();notice.value='索引重建已排队'}catch(exception){error.value=conflictMessage(exception)}})}
async function performLogout(){await logout();await router.replace('/login')}
async function switchTab(value){tab.value=value;error.value='';if(value==='operations')await loadOperations()}

onMounted(()=>loadUsers(0))
</script>

<template>
  <main class="admin-page">
    <header class="admin-header">
      <div class="admin-brand"><i aria-hidden="true"><span></span><span></span><span></span></i><div><b>鲜知管理台</b><small>ACCOUNT OPERATIONS</small></div></div>
      <nav aria-label="管理模块"><button :class="{active:tab==='users'}" @click="switchTab('users')">用户账号</button><button :class="{active:tab==='operations'}" @click="switchTab('operations')">菜谱与索引</button></nav>
      <div class="admin-account"><span>{{ session.user?.displayName }}</span><button @click="performLogout">退出</button></div>
    </header>

    <section class="admin-canvas">
      <div class="admin-heading"><div><p>{{ tab==='users'?'账号生命周期':'后台任务与检索状态' }}</p><h1>{{ tab==='users'?'用户管理':'菜谱运维' }}</h1></div><span v-if="tab==='users'">{{ total }} 个账户</span><button v-else class="solid-button" @click="rebuildIndex">重建搜索索引</button></div>
      <p v-if="error" class="admin-message error" role="alert">{{ error }}</p><p v-if="notice" class="admin-message success" role="status">{{ notice }}</p>

      <template v-if="tab==='users'">
        <form class="filters" @submit.prevent="loadUsers(0)">
          <label><span>搜索账号</span><input v-model.trim="filters.query" placeholder="用户名、称呼或邮箱" /></label>
          <label><span>角色</span><select v-model="filters.role"><option value="">全部角色</option><option value="USER">普通用户</option><option value="ADMIN">管理员</option></select></label>
          <label><span>状态</span><select v-model="filters.status"><option value="">全部状态</option><option value="ACTIVE">使用中</option><option value="DISABLED">已停用</option><option value="DELETED">待匿名化</option></select></label>
          <button class="solid-button" type="submit">筛选</button>
        </form>

        <section class="user-table" :aria-busy="loading">
          <div class="user-table-head"><span>账号</span><span>状态轨道</span><span>角色 / 会话</span><span>最近登录</span><span>操作</span></div>
          <article v-for="user in users" :key="user.id" class="user-row">
            <div class="identity"><button class="identity-button" @click="chooseUser(user)"><b>{{ user.displayName }}</b><small>@{{ user.username }} · {{ maskedEmail(user.email) }}</small></button><em v-if="user.id===session.user?.id">当前账号</em></div>
            <div class="status-track" :class="statusTone(user)" :aria-label="`账号状态：${statusLabel(user)}`"><i class="created"></i><span></span><i class="usable"></i><span></span><i class="removed"></i><b>{{ statusLabel(user) }}</b></div>
            <div class="role-cell"><b>{{ user.role==='ADMIN'?'管理员':'普通用户' }}</b><small>{{ user.activeSessionCount }} 个活跃会话<span v-if="user.passwordChangeRequired"> · 待改密</span></small></div>
            <time>{{ date(user.lastLoginAt) }}</time>
            <div class="row-menu">
              <button :disabled="!canChange(user)||busy[user.id]" @click="toggleStatus(user)">{{ user.status==='ACTIVE'?'停用':'启用' }}</button>
              <button :disabled="!canChange(user)||Boolean(user.deletedAt)||busy[user.id]" @click="resetPassword(user)">重置密码</button>
              <details><summary aria-label="更多操作">•••</summary><div><button :disabled="!canChange(user)||Boolean(user.deletedAt)" @click="toggleRole(user)">{{ user.role==='ADMIN'?'降为用户':'升为管理员' }}</button><button :disabled="!canChange(user)||Boolean(user.deletedAt)" @click="revoke(user)">强制退出</button><button v-if="!user.deletedAt" class="danger" :disabled="!canChange(user)" @click="remove(user)">删除账号</button><button v-else :disabled="!canChange(user)" @click="restore(user)">恢复账号</button></div></details>
            </div>
          </article>
          <p v-if="!loading&&!users.length" class="empty-state">没有符合条件的账号</p>
        </section>

        <section class="mobile-users" :aria-busy="loading"><article v-for="user in users" :key="user.id"><header><button @click="chooseUser(user)"><b>{{ user.displayName }}</b><small>@{{ user.username }}</small></button><em :class="statusTone(user)">{{ statusLabel(user) }}</em></header><div class="mobile-track status-track" :class="statusTone(user)"><i></i><span></span><i></i><span></span><i></i></div><dl><div><dt>角色</dt><dd>{{ user.role==='ADMIN'?'管理员':'普通用户' }}</dd></div><div><dt>活跃会话</dt><dd>{{ user.activeSessionCount }}</dd></div><div><dt>最近登录</dt><dd>{{ date(user.lastLoginAt) }}</dd></div></dl><footer><button :disabled="!canChange(user)" @click="toggleStatus(user)">{{ user.status==='ACTIVE'?'停用':'启用' }}</button><button :disabled="!canChange(user)||Boolean(user.deletedAt)" @click="resetPassword(user)">重置密码</button><button v-if="!user.deletedAt" class="danger" :disabled="!canChange(user)" @click="remove(user)">删除</button><button v-else :disabled="!canChange(user)" @click="restore(user)">恢复</button></footer></article></section>

        <footer class="pagination"><span>{{ rangeLabel }}</span><div><button :disabled="page===0" @click="loadUsers(page-1)">上一页</button><button :disabled="page+1>=totalPages" @click="loadUsers(page+1)">下一页</button></div></footer>
      </template>

      <template v-else>
        <section v-if="searchIndex" class="index-board"><article><p>当前集合</p><b>{{ searchIndex.activeCollection }}</b><small>{{ searchIndex.embeddingModelVersion }} · {{ searchIndex.vectorEnabled?'向量检索已启用':'仅 MySQL 检索' }}</small></article><article><p>已就绪</p><strong>{{ searchIndex.readyCount }}</strong><small>份菜谱</small></article><article><p>MySQL 降级</p><strong>{{ searchIndex.mysqlOnlyCount }}</strong><small>份待向量化</small></article><article><p>失败</p><strong>{{ searchIndex.failedCount }}</strong><small>份需检查</small></article></section>
        <section class="operations-list"><div class="operations-head"><div><p>导入队列</p><h2>最近任务</h2></div><button @click="loadOperations">刷新</button></div><article v-for="job in importJobs" :key="job.id"><i :class="job.status.toLowerCase()"></i><div><b>{{ job.status }}</b><small>{{ date(job.createdAt) }} · 导入 {{ job.importedCount }} / 跳过 {{ job.skippedCount }}</small><em v-if="job.lastError">{{ job.lastError }}</em></div><button v-if="['FAILED','COMPLETED_WITH_ERRORS'].includes(job.status)" :disabled="busy[job.id]" @click="retryImport(job)">重试</button></article><p v-if="!importJobs.length" class="empty-state">暂无菜谱导入任务</p></section>
        <section v-if="searchIndex?.latestRebuild" class="latest-rebuild"><p>最近索引任务</p><h2>{{ searchIndex.latestRebuild.status }}</h2><div><span>集合 {{ searchIndex.latestRebuild.collectionName }}</span><span>{{ searchIndex.latestRebuild.processedCount }} / {{ searchIndex.latestRebuild.totalCount }}</span><span>{{ date(searchIndex.latestRebuild.createdAt) }}</span></div></section>
      </template>
    </section>

    <aside v-if="selected" class="detail-panel" aria-label="账号详情"><button class="panel-close" aria-label="关闭详情" @click="selected=null">×</button><p>账号详情</p><h2>{{ selected.displayName }}</h2><small>@{{ selected.username }} · {{ selected.email }}</small><dl><div><dt>创建时间</dt><dd>{{ date(selected.createdAt) }}</dd></div><div><dt>最后更新</dt><dd>{{ date(selected.updatedAt) }}</dd></div><div><dt>删除时间</dt><dd>{{ date(selected.deletedAt) }}</dd></div><div><dt>强制改密</dt><dd>{{ selected.passwordChangeRequired?'是':'否' }}</dd></div></dl><h3>管理审计</h3><ol><li v-for="item in audits" :key="item.id"><i></i><div><b>{{ item.eventType }}</b><small>{{ date(item.createdAt) }} · {{ item.traceId }}</small></div></li></ol></aside>

    <div v-if="confirmAction" class="dialog-backdrop" @click.self="confirmAction=null"><section role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><p>需要确认</p><h2 id="confirm-title">{{ confirmAction.title }}</h2><span>{{ confirmAction.body }}</span><div><button @click="confirmAction=null">取消</button><button :class="{danger:confirmAction.danger}" autofocus @click="confirm">{{ confirmAction.label }}</button></div></section></div>
    <div v-if="temporary" class="dialog-backdrop"><section role="dialog" aria-modal="true" aria-labelledby="temporary-title"><p>仅显示一次</p><h2 id="temporary-title">临时密码</h2><code>{{ temporary.temporaryPassword }}</code><span>有效期至 {{ date(temporary.expiresAt) }}。关闭后无法再次查看。</span><div><button @click="copyPassword">复制密码</button><button class="solid-button" autofocus @click="closeTemporary">我已安全保存</button></div></section></div>
  </main>
</template>

<style scoped>
.admin-page{--canvas:#dbe8fb;--surface:#f8fbff;--ink:#203a5a;--accent:#5dabb9;--line:#bfd1e7;--muted:#687f98;min-height:100vh;background:var(--canvas);color:var(--ink);font-family:'Noto Sans SC',sans-serif}.admin-header{height:74px;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:0 clamp(22px,4vw,62px);border-bottom:1px solid #adc4de;background:rgba(248,251,255,.86);backdrop-filter:blur(14px)}.admin-brand{display:flex;align-items:center;gap:12px}.admin-brand>i{width:29px;height:38px;display:grid;align-content:space-around;padding:5px;border:2px solid var(--ink)}.admin-brand>i span{height:2px;background:var(--accent)}.admin-brand b,.admin-brand small{display:block}.admin-brand b{font-size:16px}.admin-brand small{margin-top:2px;color:var(--muted);font:800 8px 'Nunito Sans';letter-spacing:.15em}.admin-header nav{height:100%;display:flex;gap:30px}.admin-header nav button{position:relative;color:var(--muted);font-size:12px}.admin-header nav button.active{color:var(--ink);font-weight:800}.admin-header nav button.active:after{content:'';position:absolute;inset:auto 0 0;height:3px;background:var(--accent)}.admin-account{justify-self:end;display:flex;align-items:center;gap:14px;font-size:11px}.admin-account button{padding:8px 11px;border-left:1px solid var(--line);color:var(--muted)}.admin-canvas{width:min(1420px,calc(100% - 48px));margin:auto;padding:48px 0 76px}.admin-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:28px}.admin-heading p,.dialog-backdrop section>p,.detail-panel>p,.operations-head p,.latest-rebuild>p{margin:0;color:#477d8d;font-size:10px;font-weight:800;letter-spacing:.13em}.admin-heading h1{margin:4px 0 0;font-size:34px}.admin-heading>span{font:800 13px 'Nunito Sans';color:var(--muted)}.filters{display:grid;grid-template-columns:minmax(230px,1.5fr) minmax(130px,.6fr) minmax(150px,.7fr) auto;align-items:end;gap:10px;margin-bottom:16px;padding:14px;border:1px solid var(--line);background:rgba(248,251,